"use client";
/**
 * Clio stat: one thin numeral that counts up once the tile has risen in. Screen readers get the final value from the
 * start, never a number on its way.
 */
import type { ReactNode } from "react";
import { ClioTile, type ClioTileProps, clioTileAliveDelay, useClioCountUp } from "./theme";

const CSS = `
.clio-stat__body{margin-top:auto;display:flex;flex-direction:column;gap:8px;padding-top:14px}
.clio-stat__value{display:flex;align-items:baseline;gap:4px;font-size:var(--clio-stat-size,56px)}
.clio-stat__unit{font-size:.42em;font-weight:300;letter-spacing:0;color:var(--clio-ink-secondary);transition:color var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-stat__detail{display:flex;align-items:flex-start;gap:5px}
.clio-stat__trend{flex:none;width:14px;height:14px;margin-top:.5px;color:var(--clio-accent-ink);transition:color var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-stat[data-size="md"]{--clio-stat-size:40px}
.clio-stat[data-size="sm"]{--clio-stat-size:28px}
`;

/** Whole numbers with grouping, e.g. 8240 → "8,240". */
export const clioFormatNumber = (value: number, locale = "en-US", decimals = 0) =>
  new Intl.NumberFormat(locale, {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  }).format(value);

export interface ClioStatProps extends Omit<ClioTileProps, "children" | "label"> {
  /** What the number counts. */
  label?: ReactNode;
  /** The final value. */
  value: number;
  /** Where the count starts. */
  from?: number;
  decimals?: number;
  /** A unit after the numeral, e.g. "%". */
  unit?: string;
  /** One line under the numeral. */
  detail?: ReactNode;
  /** Draws a small rising or falling mark before the detail. */
  trend?: "up" | "down" | null;
  /** Numeral size. */
  size?: "lg" | "md" | "sm";
  /** Count up after the rise. Off, the final value shows at once. */
  animate?: boolean;
  /** Milliseconds the count takes. */
  duration?: number;
  locale?: string;
  /** Your own formatting of the shown number. */
  format?: (value: number) => string;
  /** What screen readers hear for the value; the formatted final value and unit by default. */
  valueLabel?: string;
}

export function ClioStat({
  label = "Saved this week",
  value,
  from = 0,
  decimals = 0,
  unit,
  detail,
  trend = null,
  size = "lg",
  animate = true,
  duration,
  locale = "en-US",
  format,
  valueLabel,
  riseIndex,
  riseDelay,
  className,
  ...tile
}: ClioStatProps) {
  const shown = useClioCountUp(value, {
    from,
    decimals,
    duration,
    delay: clioTileAliveDelay(riseIndex, riseDelay),
    enabled: animate,
  });
  const text = (n: number) => (format ? format(n) : clioFormatNumber(n, locale, decimals));
  return (
    <ClioTile
      {...tile}
      label={label}
      riseIndex={riseIndex}
      riseDelay={riseDelay}
      className={className ? `clio-stat ${className}` : "clio-stat"}
      data-size={size}
    >
      <style>{CSS}</style>
      <div className="clio-stat__body">
        <p className="clio-stat__value">
          <span className="clio-numeral" aria-hidden="true">
            {text(shown)}
          </span>
          {unit ? (
            <span className="clio-stat__unit" aria-hidden="true">
              {unit}
            </span>
          ) : null}
          <span className="clio-sr">{valueLabel ?? `${text(value)}${unit ? ` ${unit}` : ""}`}</span>
        </p>
        {detail ? (
          <p className="clio-caption clio-stat__detail">
            {trend ? (
              <svg className="clio-stat__trend" viewBox="0 0 14 14" aria-hidden="true">
                <path
                  d={trend === "up" ? "M3 9.5 7 5.5l4 4" : "M3 4.5l4 4 4-4"}
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="1.4"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            ) : null}
            <span>{detail}</span>
          </p>
        ) : null}
      </div>
    </ClioTile>
  );
}
